script:
if doc.employee_permission:

    # Get allowed number of entries
    allowed_entries = frappe.db.get_value(
        "Employee Permission",
        doc.employee_permission,
        "no_of_entry_permission"
    ) or 0

        # Convert safely to integer
    allowed_entries = int(allowed_entries or 0)

    # Proceed only if limit is defined
    if allowed_entries > 0:

        # Count existing Employee In records
        used_entries = frappe.db.count(
            "Employee In",
            {
                "employee_permission": doc.employee_permission
            }
        )

        # Validation
        if used_entries >= allowed_entries:
            frappe.throw(
                f"Entry limit exceeded.<br>"
                f"Allowed entries: {allowed_entries}<br>"
                f"Already used: {used_entries}"
            )

QC_WAREHOUSES = (
    "RM Under Test Store - (A) - BS",
    "RM Under Test Store - (B) - BS",
    "RM Under Test Store - (C) - BS",
    "PM Under Test Store - (A) - BS",
    "PM Under Test Store - (B) - BS",
    "PM Under Test Store - (C) - BS",
)

def get_batch_no_from_bundle(bundle):
    if not bundle:
        return None

    return frappe.db.get_value(
        "Serial and Batch Entry",
        {"parent": bundle},
        "batch_no"
    )

created = False

for item in doc.items:

    target_warehouse = item.t_warehouse or doc.to_warehouse

    frappe.log_error(
        f"Checking item {item.item_code} | Warehouse: {target_warehouse}",
        "QC TRACE"
    )

    if not target_warehouse or target_warehouse not in QC_WAREHOUSES:
        continue

    has_batch = frappe.db.get_value("Item", item.item_code, "has_batch_no")
    if not has_batch:
        continue

    batch_no = item.batch_no or get_batch_no_from_bundle(item.serial_and_batch_bundle)

    if not batch_no:
        frappe.throw(
            f"Batch No is mandatory for Quality Inspection. "
            f"Please set Batch No for Item <b>{item.item_code}</b>"
        )

    if frappe.db.exists(
        "Quality Inspection",
        {
            "reference_type": "Stock Entry",
            "reference_name": doc.name,
            "item_code": item.item_code,
            "batch_no": batch_no,
        }
    ):
        continue

    qi = frappe.get_doc({
        "doctype": "Quality Inspection",
        "inspection_type": "Incoming",
        "reference_type": "Stock Entry",
        "reference_name": doc.name,
        "item_code": item.item_code,
        "batch_no": batch_no,
        "sample_size": 1,
        "company": doc.company,
        "inspected_by": frappe.session.user,
    })

    qi.insert(ignore_permissions=True)
    created = True

if not created:
    frappe.log_error("No Quality Inspection created", "QC RESULT")

def get_section(warehouse):
    if "(A)" in warehouse:
        return "A"
    if "(B)" in warehouse:
        return "B"
    if "(C)" in warehouse:
        return "C"
    return None


def get_store_type(warehouse):
    if "Receiving Store" in warehouse:
        return "RECEIVING"
    if "Under Test Store" in warehouse:
        return "UNDER_TEST"
    if "Approved Store" in warehouse:
        return "APPROVED"
    if "Reject Store" in warehouse:
        return "REJECT"
    if "Work In Progress" in warehouse:
        return "WIP"
    return None


def get_material_type(warehouse):
    if "RM" in warehouse:
        return "RM"
    if "PM" in warehouse:
        return "PM"
    return None


for row in doc.items:

    from_wh = row.s_warehouse or doc.from_warehouse
    to_wh = row.t_warehouse or doc.to_warehouse

    if not from_wh or not to_wh:
        continue

    from_section = get_section(from_wh)
    to_section = get_section(to_wh)

    if from_section != to_section:
        frappe.throw(f"Section mismatch not allowed: {from_wh} → {to_wh}")

    from_type = get_store_type(from_wh)
    to_type = get_store_type(to_wh)

    material_type = get_material_type(from_wh)

    # =========================
    # RECEIVING → UNDER TEST
    # =========================
    if from_type == "RECEIVING":
        if to_type != "UNDER_TEST":
            frappe.throw("Receiving Store can move only to Under Test Store")

    # =========================
    # UNDER TEST → APPROVED / REJECT
    # =========================
    elif from_type == "UNDER_TEST":
        if to_type not in ["APPROVED", "REJECT"]:
            frappe.throw("Under Test Store can move only to Approved or Reject Store")

    # =========================
    # REJECT → UNDER TEST / RECEIVING
    # =========================
    elif from_type == "REJECT":
        if to_type not in ["UNDER_TEST", "RECEIVING"]:
            frappe.throw("Reject Store can move only to Under Test or Receiving")

    # =========================
    # APPROVED → ANY SAME MATERIAL TYPE STORE IN SAME SECTION
    # =========================
    elif from_type == "APPROVED":
        if material_type and material_type not in to_wh:
            frappe.throw("Approved Store can move only to same material type store in same section")

    # =========================
    # WIP → APPROVED (Same Section)
    # =========================
    elif from_type == "WIP":
        if to_type != "APPROVED":
            frappe.throw("WIP can move only to Approved Store")

if doc.stock_entry_type == "Material Transfer":

    requires_approval = False

    for item in doc.items:

        if (
            item.s_warehouse
            and item.t_warehouse
            and "Reject" in item.s_warehouse
            and "Under Test" in item.t_warehouse
        ):
            requires_approval = True
            break

    if requires_approval and doc.custom_status != "Approved":
        frappe.throw("GM Approval is required for transfer from Reject Store to Under Test Store.")

# check if Status field was modified
if doc.has_value_changed("custom_status"):

    user_roles = frappe.get_roles(frappe.session.user)

    # allow only GM
    if "General Manager" not in user_roles:
        frappe.throw("Only General Manager can change the Status of this Stock Entry.")

#frappe.msgprint("Quality Inspection validation script triggered");
for row in doc.items:

    #frappe.msgprint("Checking 1 ");   

    if not row.batch_no:
        continue

    #frappe.msgprint("Checking 2 ");   


    source = row.s_warehouse or ""
    target = row.t_warehouse or ""

    # Check movement from Under Test warehouse
    if "Under Test" in source:

        # Find Quality Inspection for the batch
        #frappe.msgprint("Checking Batch: " + str(row.batch_no));

        qi = frappe.db.get_value(
            "Quality Inspection",
            {"batch_no": row.batch_no},
            ["name", "status", "docstatus"],
            as_dict=True
        )

        if not qi:
            frappe.throw(
                "No Quality Inspection found for Batch " + row.batch_no
            )

        # Ensure QI is submitted
        if qi.docstatus != 1:
            frappe.throw(
                "Quality Inspection " + qi.name +
                " for Batch " + row.batch_no +
                " must be Submitted before stock movement."
            )

        # Movement to Approved Store
        if "Approved" in target:

            if qi.status != "Accepted":
                frappe.throw(
                    "Batch " + row.batch_no +
                    " cannot move to Approved Store because Quality Inspection " +
                    qi.name + " is not Accepted."
                )
        #frappe.msgprint("Checking Bat: " + str(row.batch_no)); 
        # Movement to Rejected Store
        if "Rejected" in target:

            if qi.status != "Rejected":
                frappe.throw(
                    "Batch " + row.batch_no +
                    " cannot move to Rejected Store because Quality Inspection " +
                    qi.name + " is not Rejected."
                )

        # Prevent movement anywhere else
        if "Approved" not in target and "Rejected" not in target:
            frappe.throw(
                "Batch " + row.batch_no +
                " can only move from Under Test to Approved or Rejected warehouse."
            )

if doc.custom_batch_option == "Select Semi-Finished Batch":

    if not doc.custom_linked_batch:
        frappe.throw("Please select Semi-Finished Batch")

    if not doc.custom_linked_batch.endswith("-S"):
        frappe.throw("Invalid Semi-Finished Batch")

if doc.custom_batch_option == "Select Finished Batch":

    if doc.custom_linked_batch.endswith("-S"):
        frappe.throw("Please select Finished Batch")
